import React, { useState, useRef, useEffect, useCallback } from 'react';
import { attendanceAPI } from './api_service';

const CameraRecognition = ({ addNotification }) => {
  const videoRef = useRef(null);
  const streamRef = useRef(null);
  const captureIntervalRef = useRef(null);
  const isProcessingRef = useRef(false);

  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const [autoMode, setAutoMode] = useState(true);
  const [frameCount, setFrameCount] = useState(0);
  const [lastDetection, setLastDetection] = useState(null);

  // ====================== DÉMARRAGE CAMÉRA ======================
  useEffect(() => {
    let isMounted = true;

    const startCamera = async () => {
      try {
        console.log('🎥 Démarrage caméra...');
        const stream = await navigator.mediaDevices.getUserMedia({
          video: {
            facingMode: 'user',
            width: { ideal: 1280 },
            height: { ideal: 720 }
          },
          audio: false
        });

        if (!isMounted) {
          stream.getTracks().forEach(track => track.stop());
          return;
        }

        streamRef.current = stream;
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          console.log('✅ Caméra démarrée avec succès');
        }
      } catch (err) {
        console.error('❌ Erreur caméra:', err);
        setError("Impossible d'accéder à la caméra");
        addNotification("❌ Erreur d'accès à la caméra", 'error');
      }
    };

    startCamera();

    return () => {
      isMounted = false;
      stopAll();
    };
  }, [addNotification]);

  // ====================== MODE AUTO ======================
  const processFrame = useCallback(async () => {
    if (!videoRef.current || isProcessingRef.current) return;

    isProcessingRef.current = true;

    try {
      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth || 1280;
      canvas.height = videoRef.current.videoHeight || 720;

      const ctx = canvas.getContext('2d', { willReadFrequently: true });
      ctx.drawImage(videoRef.current, 0, 0);

      const imageBase64 = canvas.toDataURL('image/jpeg', 0.82); // légèrement baissé pour perf

      setFrameCount(prev => prev + 1);

      const response = await attendanceAPI.recognize(imageBase64);
      const data = response?.data;

      if (data?.success && data.student) {
        const detectionTime = new Date().toLocaleTimeString();

        setResult({
          success: true,
          name: data.student,
          email: data.email || 'N/A',
          confidence: (data.confidence * 100).toFixed(1),
          attendanceId: data.attendance_id,
          timestamp: detectionTime,
          message: `✅ ${data.student} enregistré !`
        });

        setLastDetection(detectionTime);
        addNotification(`✅ ${data.student} détecté`, 'success');

        // Pause temporaire après détection réussie
        setAutoMode(false);
        setTimeout(() => setAutoMode(true), 3500);
      } 
      else if (data?.message === 'Unknown face - no match found') {
        // Silencieux pour ne pas spammer la console
      }
    } catch (err) {
      console.warn('⚠️ Erreur reconnaissance:', err.message);
    } finally {
      isProcessingRef.current = false;
    }
  }, [addNotification]);

  // Gestion de l'intervalle auto
  useEffect(() => {
    if (!autoMode) {
      if (captureIntervalRef.current) {
        clearInterval(captureIntervalRef.current);
        captureIntervalRef.current = null;
      }
      return;
    }

    console.log('▶️ Mode AUTO activé - Capture toutes les 500ms');
    setError(null);

    captureIntervalRef.current = setInterval(() => {
      processFrame();
    }, 500);

    return () => {
      if (captureIntervalRef.current) {
        clearInterval(captureIntervalRef.current);
        captureIntervalRef.current = null;
      }
    };
  }, [autoMode, processFrame]);

  // ====================== CAPTURE MANUELLE ======================
  const handleManualCapture = async () => {
    if (!videoRef.current || loading) return;

    setLoading(true);
    setError(null);
    setResult(null);

    try {
      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth || 1280;
      canvas.height = videoRef.current.videoHeight || 720;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(videoRef.current, 0, 0);

      const imageBase64 = canvas.toDataURL('image/jpeg', 0.92);

      const response = await attendanceAPI.recognize(imageBase64);
      const data = response?.data;

      if (data?.success && data.student) {
        const detectionTime = new Date().toLocaleTimeString();

        setResult({
          success: true,
          name: data.student,
          email: data.email || 'N/A',
          confidence: (data.confidence * 100).toFixed(1),
          attendanceId: data.attendance_id,
          timestamp: detectionTime,
          message: `✅ ${data.student} enregistré !`
        });

        setLastDetection(detectionTime);
        addNotification(`✅ ${data.student} détecté`, 'success');
      } else {
        const msg = data?.message || 'Visage non reconnu';
        setError(msg);
        setResult({
          success: false,
          message: msg,
          confidence: ((data?.confidence || 0) * 100).toFixed(1)
        });
        addNotification('⚠️ Visage non reconnu', 'error');
      }
    } catch (err) {
      const msg = err?.message || 'Erreur serveur';
      setError(msg);
      addNotification(`❌ ${msg}`, 'error');
    } finally {
      setLoading(false);
    }
  };

  const stopAll = useCallback(() => {
    if (captureIntervalRef.current) {
      clearInterval(captureIntervalRef.current);
      captureIntervalRef.current = null;
    }
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
    setAutoMode(false);
  }, []);

  // Nettoyage final
  useEffect(() => {
    return () => stopAll();
  }, [stopAll]);

  return (
    <div style={styles.container}>
      <h1 style={styles.title}>👤 Reconnaissance Faciale</h1>

      <div style={styles.videoContainer}>
        <video
          ref={videoRef}
          autoPlay
          playsInline
          muted
          style={styles.video}
        />

        <div style={{
          ...styles.statusBadge,
          background: autoMode ? 'rgba(34, 197, 94, 0.95)' : 'rgba(107, 114, 128, 0.9)'
        }}>
          {autoMode ? '🔄 Scanning en cours...' : '⏸️ En pause'}
        </div>

        <div style={styles.frameCounter}>
          Frames : {frameCount}
        </div>
      </div>

      <div style={styles.actions}>
        <button onClick={handleManualCapture} disabled={loading} style={{
          ...styles.btn,
          background: loading ? '#94A3B8' : '#10B981'
        }}>
          {loading ? '⏳ Traitement...' : '📸 Capture Manuelle'}
        </button>

        <button
          onClick={() => setAutoMode(!autoMode)}
          style={{
            ...styles.btn,
            background: autoMode ? '#EF4444' : '#6366F1'
          }}
        >
          {autoMode ? '⏸️ Arrêter Auto' : '▶️ Démarrer Auto'}
        </button>

        <button onClick={stopAll} style={{ ...styles.btn, background: '#64748B' }}>
          🛑 Fermer Caméra
        </button>
      </div>

      {autoMode && (
        <div style={styles.autoStatus}>
          <span style={styles.pulse} /> Détection continue (toutes les 500ms)
        </div>
      )}

      {lastDetection && (
        <div style={styles.lastDetectionBox}>
          ⏰ Dernière détection : {lastDetection}
        </div>
      )}

      {error && <div style={styles.errorBox}>❌ {error}</div>}

      {result && (
        <div style={{
          ...styles.resultBox,
          borderLeft: result.success ? '5px solid #10B981' : '5px solid #EF4444'
        }}>
          {result.success ? (
            <>
              <h3 style={{ color: '#10B981', margin: '0 0 12px 0' }}>
                {result.message}
              </h3>
              <div style={styles.resultGrid}>
                <p><strong>👤 Nom :</strong> {result.name}</p>
                <p><strong>📧 Email :</strong> {result.email}</p>
                <p><strong>🎯 Confiance :</strong> {result.confidence}%</p>
                <p><strong>🆔 ID Présence :</strong> {result.attendanceId}</p>
                <p><strong>🕒 Heure :</strong> {result.timestamp}</p>
              </div>
            </>
          ) : (
            <>
              <h3 style={{ color: '#EF4444' }}>❌ Non Reconnu</h3>
              <p>{result.message}</p>
              <p style={{ fontSize: '0.85rem', color: '#666' }}>
                Confiance : {result.confidence}%
              </p>
            </>
          )}
        </div>
      )}

      <div style={styles.debugBox}>
        <p><strong>Mode Auto :</strong> {autoMode ? '✅ Actif' : '❌ Inactif'}</p>
        <p><strong>Frames traités :</strong> {frameCount}</p>
        <p><strong>En traitement :</strong> {isProcessingRef.current ? '🔄 Oui' : '✓ Non'}</p>
      </div>
    </div>
  );
};
